local function createView()
    local nodes = {}
    local skipped = {}
    local enumCache = {}
    local function enum(name,value)
        local key=name..":"..value
        if enumCache[key] then return enumCache[key] end
        local found=Enum[name]
        for _,item in ipairs(found:GetEnumItems()) do
            if item.Value==value then enumCache[key]=item; return item end
        end
        error("Unknown enum value "..key)
    end
    local function set(id,property,build)
