end)()
local Upgrader=(function()
--!nocheck
-- Injected state machine. No game-specific API calls in this module.
local Upgrader={}
function Upgrader.new(d)
    local self={alive=true,rows={},generation=0,cursor=0}
    local function validNumber(v) return type(v)=="number" and v==v and v>=0 and v<10000 and v%1==0 end
    function self:add(unit)
        if not self.rows[unit] then self.rows[unit]={unit=unit,identity=d.identity and d.identity(unit),enabled=false,target=0,status="OFF",nextAttempt=0} end
        return self.rows[unit]
    end
    function self:enable(unit,on)
        local row=self:add(unit)
        assert(d.valid(unit),"Unit no longer exists")
        local level,maximum=d.levels(unit)
        assert(validNumber(level) and validNumber(maximum) and level<=maximum,"Upgrade/max_upgrade are unavailable")
        row.enabled=on; row.blocked=nil; row.status=on and "QUEUED" or "OFF"
        d.changed(row)
    end
    function self:target(unit,value)
        local row=self:add(unit)
        assert(value=="max" or validNumber(value),"Invalid target upgrade")
        row.target=value
        d.changed(row)
    end
    function self:stop()
        self.generation=self.generation+1
        for _,row in pairs(self.rows) do row.enabled=false;row.status="STOPPED";d.changed(row) end
    end
    function self:destroy() self:stop();self.alive=false end
    function self:step(row)
        if not self.alive or not row.enabled or row.blocked then return end
        if not d.valid(row.unit) or (d.identity and d.identity(row.unit)~=row.identity) then row.enabled=false;row.status="REMOVED / REPLACED";d.changed(row);return end
        local current,maximum=d.levels(row.unit)
        if not validNumber(current) or not validNumber(maximum) or current>maximum then
            row.enabled=false;row.status="LEVEL UNAVAILABLE";d.changed(row);return
        end
        local target=row.target=="max" and maximum or math.min(row.target,maximum)
        if current>=target then row.enabled=false;row.status="DONE";d.changed(row);return end
        if row.awaitLevel then
            if row.lastCall and row.lastCall.done and not row.lastCall.values[1] then
                row.blocked=true;row.enabled=false;row.status="ERROR: late invocation failure";d.changed(row);return
            elseif row.lastCall and row.lastCall.done and row.lastCall.values[1] and row.lastCall.values[2]==false then row.awaitLevel=nil
            elseif current>row.awaitLevel then row.awaitLevel=nil;row.status="LEVEL CONFIRMED"
            else row.status="WAIT LEVEL REPLICATION";return end
        end
        if d.broker.pending or not d.canRun() or d.clock()<row.nextAttempt then return end
        local remote=d.remote()
        if not remote then row.status="WAIT REMOTE";return end
        local call={done=false}
        row.lastCall=call;row.awaitLevel=current
        local generation=self.generation
        d.broker.pending=call
        row.status="UPGRADING";d.changed(row)
        d.spawn(function()
            call.values=table.pack(pcall(d.invoke,remote,row.unit))
            call.done=true
            if d.broker.pending==call then d.broker.pending=nil end
        end)
        local started=d.clock()
        while not call.done do
            if not self.alive or self.generation~=generation or not row.enabled then return end
            if d.clock()-started>=15 and row.status~="WAIT SERVER" then row.status="WAIT SERVER";d.changed(row) end
            d.wait(0.05)
        end
        if not self.alive or self.generation~=generation or not row.enabled then return end
        if not d.valid(row.unit) or (d.identity and d.identity(row.unit)~=row.identity) then row.enabled=false;row.status="REMOVED / REPLACED";d.changed(row);return end
        if not call.values[1] then
            row.blocked=true;row.enabled=false;row.status="ERROR: "..tostring(call.values[2]):sub(1,160);d.changed(row);return
        end
        -- Replicated level, not a generic successful pcall, confirms the effect.
        local deadline=d.clock()+2
        local after=d.levels(row.unit)
        while after==current and d.clock()<deadline do
            if not self.alive or self.generation~=generation or not row.enabled or not d.valid(row.unit) then return end
            d.wait(0.05);after=d.levels(row.unit)
        end
        if type(after)=="number" and after>current then
            row.awaitLevel=nil
            row.status="LEVEL "..after
            row.nextAttempt=d.clock()+1
        elseif call.values[2]==false then
            row.awaitLevel=nil
            row.status="WAIT / RETRY IN 2s"
            row.nextAttempt=d.clock()+2
        else
            -- True/nil without replicated progress is ambiguous. Do not double-upgrade.
            row.awaitLevel=current
            row.status="WAIT LEVEL REPLICATION"
        end
        d.changed(row)
    end
    function self:tick()
        local list={}
        for _,row in pairs(self.rows) do if row.enabled then list[#list+1]=row end end
        if #list==0 then return end
        self.cursor=self.cursor%#list+1
        self:step(list[self.cursor])
    end
    return self
end

return Upgrader
end)()
local Motion=(function()
-- Client-only navigation cosmetics. No gameplay or remote dependencies.
local Motion = {}
function Motion.new(tweens, reduced, delay)
    local self = {generation=0, active={}, restore={}, alive=true}
    function self:cancel()
        self.generation+=1
        for _,t in ipairs(self.active) do t:Cancel();t:Destroy() end
        self.active={}
        for _,entry in ipairs(self.restore) do
            if entry.object.Parent then
                for key,value in pairs(entry.goal) do entry.object[key]=value end
            end
        end
        self.restore={}
    end
    function self:play(object,goal,duration)
        local t=tweens:Create(object,TweenInfo.new(duration,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),goal)
        self.active[#self.active+1]=t;t:Play()
    end
    function self:enter(highlight,row,blocks,first)
        local previous=highlight.AbsolutePosition
        self:cancel()
        local token=self.generation
        highlight.Parent=row
        highlight.AnchorPoint=Vector2.new(0,0)
        highlight.Size=UDim2.fromScale(1,1)
        local instant=first or reduced()
        highlight.Position=UDim2.fromScale(0,0)
        if not instant and row.AbsoluteSize.X>0 and row.AbsoluteSize.Y>0 then
            highlight.Position=UDim2.fromScale((previous.X-row.AbsolutePosition.X)/row.AbsoluteSize.X,
                (previous.Y-row.AbsolutePosition.Y)/row.AbsoluteSize.Y)
            self:play(highlight,{Position=UDim2.fromScale(0,0)},0.22)
        end
        if instant then return end
        -- Fade the original instances; preserve layouts, hit targets and model hierarchy.
        for index,block in ipairs(blocks) do
            local entries={}
            local objects=block:GetDescendants();table.insert(objects,1,block)
            for _,object in ipairs(objects) do
                local goal={}
                if object:IsA("GuiObject") then goal.BackgroundTransparency=object.BackgroundTransparency end
                if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
                    goal.TextTransparency=object.TextTransparency;goal.TextStrokeTransparency=object.TextStrokeTransparency
                end
                if object:IsA("ImageLabel") or object:IsA("ImageButton") then goal.ImageTransparency=object.ImageTransparency end
                if object:IsA("UIStroke") then goal.Transparency=object.Transparency end
                if next(goal) then
                    local entry={object=object,goal=goal}
                    entries[#entries+1]=entry;self.restore[#self.restore+1]=entry
                    for key in pairs(goal) do object[key]=1 end
                end
            end
            delay((index-1)*0.055,function()
                if not self.alive or token~=self.generation then return end
                for _,entry in ipairs(entries) do
                    if entry.object.Parent then self:play(entry.object,entry.goal,0.24) end
                end
            end)
        end
        delay(0.24+math.max(0,#blocks-1)*0.055,function()
            if self.alive and token==self.generation then self:cancel();highlight.Position=UDim2.fromScale(0,0) end
        end)
    end
    function self:destroy() self.alive=false;self:cancel() end
    return self
end
return Motion

end)()
--!nocheck
-- GH_AAUI integration v2. Executor APIs remain optional capabilities.
