if env[runtimeKey] and env[runtimeKey].alive then
    assert(env[runtimeKey].revision=="5.3", "Update available: SAVE your macro, click Unload Script in the old GUI, then run this file again")
    env[runtimeKey].show()
    return
end
assert(not (env.__GHAAUI_Broker_V2 and env.__GHAAUI_Broker_V2.pending), "Old v2 request pending; wait or rejoin")
assert(not (env.__GHAAUI_Broker_V3 and env.__GHAAUI_Broker_V3.pending),"Old v3 request pending; wait or rejoin")
assert(not (env.__GHAAUI_Broker_V4 and env.__GHAAUI_Broker_V4.pending),"Old v4 request pending; wait or rejoin")
local broker = env[brokerKey] or {}
if not broker.pending and type(broker.blocked)=="string" and broker.blocked:find("Unknown server response",1,true) then
    broker.blocked=nil
end
env[brokerKey] = broker
local old = env.__AAPlacementRecorderV1
if old then
    assert(not old.pending, "v1 request pending; wait or rejoin before opening v2")
    old.mode, old.generation = "IDLE", old.generation + 1
    if old.blocked then broker.blocked = old.blocked end
    if old.gui then old.gui:Destroy() end
end
local gui, nodes = createView()
local function n(id)
    local actual=id>=163 and id+59 or id
