end
local runtime = {alive = true, revision="5.3", connections = {}}
local settings = {language = "English", scale = 100, opacity = 100, delay = 1000,
    autoHide = false, autoLoad = false, hotkey = "RightControl"}
local prefix = "GH_AA_" .. player.UserId .. "_"
local maxBytes = 2 * 1024 * 1024
local core, popup, dragging, keyCapture
local confirm = {}
local savedNames, presets = {}, {}
local selectedName, lastMessage = "", "Ready"
local profileButtons={}
local changedSettings, refresh, applySettings, persistSettings, closePopup, populateProfiles
local queueAPI = queue_on_teleport or (type(syn) == "table" and syn.queue_on_teleport)
local RU = {
    [31]="Anime Adventures",[33]="Макросы",[54]="Макросы",[61]="Настройки",
    [90]="МАКРОС",[92]="Имя макроса",[110]="Воспроизведение",[120]="Сохранённые макросы",
    [181]="ПРОГРЕСС",[183]="Статус",[186]="Шаг",[189]="Задержка шага (мс)",
    [199]="Запись размещений и автоулучшения в панели ниже. Продажа пока не подключена.",
