local function metadata(model,id)
    local old=core.unitCatalog[id] or {}
    local meta={};for k,v in pairs(old) do meta[k]=v end
    meta.modelName=model.Name
    local _,maximum=levels(model);meta.maxUpgrade=maximum or meta.maxUpgrade
    local name,icon
    if not old.displayName or (not old.icon and not old.portrait) then name,icon=guiMetadata(model,id) end
    if not name then
        for _,key in ipairs({"DisplayName","display_name","UnitName","unit_name"}) do
            local value=model:GetAttribute(key)
            if displayString(value) and value~=model.Name then name=value;break end
        end
    end
    if not name then
        for _,obj in ipairs(model:GetDescendants()) do
            if obj:IsA("TextLabel") and (obj.Name=="UnitName" or obj.Name=="DisplayName") and displayString(obj.Text) then name=obj.Text;break end
        end
    end
    if not meta.customName and name then meta.displayName=name end
    if icon and icon~="" then meta.icon=icon end
    if not meta.portrait then
        local ok,value=pcall(Portrait.capture,model)
        if ok and value then
            local valid,clean=pcall(Portrait.validate,value,Recorder.validateCFrame)
            if valid then meta.portrait=clean end
        end
    end
    if not runtime.portraitModels[id] then
        local ok,value=pcall(Portrait.clone,model)
        if ok then runtime.portraitModels[id]=value end
    end
    core.unitCatalog[id]=meta
    core.dirty=true
    return meta
end
local function seek(entry,before,claimed,alive,done)
    task.spawn(function()
        local deadline=os.clock()+6
        local unit,status
        repeat
            if not runtime.alive or not alive() then return end
            unit,status=Plan.candidate(entry,models(),before,claimed,position,function(u)
                local meta=core.unitCatalog[entry.id]
                return not meta or not meta.modelName or u.Name==meta.modelName
            end)
            if unit then done(unit);return end
            task.wait(0.1)
        until os.clock()>=deadline
        if alive() then report("Placement model not bound: "..tostring(status)..". Upgrades stay off for this placement.") end
    end)
end
runtime.recordStart=function()
    resetPlan();recordBaseline=snapshot()
end
runtime.recorded=function(owner,entry,index)
    local source,token=owner.entries,owner.recordToken
    seek(entry,recordBaseline,recordBaseline,function() return owner.entries==source and owner.recordToken==token end,
        function(unit) recordBaseline[unit]=true;metadata(unit,entry.id) end)
end
runtime.playStart=function(owner)
    engine:stop();engine.rows={};plan:start(owner.entries)
end
runtime.beforePlacement=function(owner)
    return {before=snapshot(),token=plan.token,source=owner.entries}
end
runtime.placed=function(owner,entry,index,generation,context)
    if not context or context.source~=core.entries or context.token~=plan.token then return end
    local token=context.token
    seek(entry,context.before,plan.claimed,function()
        return plan.active and plan.token==token and core.entries==context.source
    end,function(unit)
        if not plan:bind(index,unit,token) then return end
        metadata(unit,entry.id)
        engine:add(unit)
        plan:apply(index,engine,function(u) return folder() and u.Parent==folder() end,upgradePaused)
    end)
end
