local cards={};local sourceRef,sourceCount,renderedPage
local function clearCards()
    for _,refs in pairs(cards) do
        for _,connection in ipairs(refs.connections) do connection:Disconnect() end
        baseTransparency[refs.card]=nil
        for _,obj in ipairs(refs.card:GetDescendants()) do baseTransparency[obj]=nil end
        refs.card:Destroy()
    end
    cards={}
end
local function setTarget(index,value)
    core:idle()
    local entry=assert(core.entries[index],"Placement no longer exists")
    entry.upgradeTarget=value;core.dirty=true
    plan:apply(index,engine,function(u) return folder() and u.Parent==folder() end,upgradePaused)
end
local function addCard(index,entry)
    local card=raw(154):Clone();card.Name="MacroPlacement_"..index;card.Visible=true;card.LayoutOrder=index;card.Parent=raw(152)
    local body=card:FindFirstChild("Frame");local display=body:FindFirstChild("Frame")
    local nameLabel=display:FindFirstChild("UnitName")
    local nameBox=nameLabel
    nameBox.Visible=true
    nameBox.Name="DisplayName"
    nameBox.Text=""
    nameBox.TextTruncate=Enum.TextTruncate.AtEnd
    -- Keep the author's original single centered name line, not an editor/status stack.
    local count=display:FindFirstChild("UpgradesCount");local label=count:FindFirstChildWhichIsA("TextLabel")
    local buttons={};for _,v in ipairs(count:GetChildren()) do if v:IsA("TextButton") then buttons[#buttons+1]=v end end
    table.sort(buttons,function(a,b) return a.Position.X.Offset<b.Position.X.Offset end)
    local image=display:FindFirstChild("UnitImage");local viewport=image:FindFirstChildWhichIsA("ViewportFrame")
    for _,v in ipairs(viewport:GetChildren()) do v:Destroy() end
    viewport.Visible=false
    image.BackgroundTransparency=1;viewport.BackgroundTransparency=1
    for _,child in ipairs(image:GetChildren()) do if child:IsA("Frame") then child.Visible=false end end
    local icon=Instance.new("ImageLabel");icon.Name="SavedIcon";icon.BackgroundTransparency=1
    icon.Size=UDim2.fromScale(1,1);icon.Visible=false;icon.ZIndex=viewport.ZIndex;icon.Parent=image
    for _,obj in ipairs(image:GetDescendants()) do if obj:IsA("TextLabel") then obj.Visible=false end end
    -- Row-wide clicks do not change upgrade targets or silently select Max.
    local toggle=body:FindFirstChildWhichIsA("TextButton");toggle.Active=false;toggle.Interactable=false
    local refs={card=card,index=index,name=nameBox,label=label,viewport=viewport,icon=icon,connections={}}
    card.Visible=true
    cards[index]=refs
    local function event(signal,fn) connect(signal,safe(fn),refs.connections) end
    event(buttons[1].Activated,function()
        local meta=core.unitCatalog[entry.id] or {};local value=Plan.target(entry)
        setTarget(index,math.max(0,(value=="max" and (meta.maxUpgrade or 1) or value)-1))
    end)
    event(buttons[2].Activated,function()
        local meta=core.unitCatalog[entry.id] or {};local value=Plan.target(entry)
        if value=="max" then return end
        setTarget(index,math.min(meta.maxUpgrade or 999,value+1))
    end)
    local max=Instance.new("TextButton");max.Name="ChooseMax";max.Text="";max.BackgroundTransparency=1;max.Position=label.Position;max.Size=label.Size;max.ZIndex=label.ZIndex+1;max.Parent=count
    event(max.Activated,function()
        if confirmAction("set Max for placement "..index,tostring(core.recordToken)..":"..index) then setTarget(index,"max") end
    end)
    return refs
end
local function refreshPlan()
    if plan:select(core.entries) then engine:stop();engine.rows={};page=1 end
    if runtime.resolveCatalog then runtime.resolveCatalog() end
    local total=#core.entries;local pages=math.max(1,math.ceil(total/20));page=math.clamp(page,1,pages)
    if sourceRef~=core.entries or sourceCount~=total or renderedPage~=page then
        clearCards();sourceRef=core.entries;sourceCount=total;renderedPage=page
        for index=(page-1)*20+1,math.min(page*20,total) do addCard(index,core.entries[index]) end
    end
    for index,refs in pairs(cards) do
        local entry=core.entries[index];local meta=core.unitCatalog[entry.id] or {}
        if type(entry.upgradeTarget)=="number" and meta.maxUpgrade and entry.upgradeTarget>meta.maxUpgrade then
            entry.upgradeTarget=meta.maxUpgrade;core.dirty=true
        end
        refs.name.Text=Catalog.friendly(meta.displayName) and meta.displayName or
            (runtime.catalogState=="reading" and "Loading…" or "Data unavailable")
        local live=plan.bindings[index]
        local level,maximum
        if live and live.Parent==folder() then level,maximum=levels(live) end
        local maxed=level~=nil and maximum~=nil and maximum>0 and level>=maximum
        refs.label.Text=(maxed or Plan.target(entry)=="max") and "MAX" or tostring(Plan.target(entry))
        local available=false
        if refs.meta~=meta then
            refs.meta=meta;refs.viewport.Visible=false;refs.icon.Visible=false;refs.ready=false
            if meta.icon and meta.icon~="" then
                refs.icon.Image=meta.icon;refs.icon.Visible=true
            elseif runtime.portraitModels[entry.id] then
                local ok,rendered=pcall(Portrait.renderModel,refs.viewport,runtime.portraitModels[entry.id]);refs.ready=ok and rendered
            elseif meta.portrait then
                local ok,rendered=pcall(Portrait.render,refs.viewport,meta.portrait);refs.ready=ok and rendered
            end
        end
        available=refs.ready or (refs.icon.Visible and refs.icon.IsLoaded)
        refs.resolved=Catalog.friendly(meta.displayName) and available
        refs.card.Visible=true
    end
    navigation.Visible=pages>1
    pageLabel.Text=page.." / "..pages.." · "..total.." placements"
    local unresolved=0
    for _,refs in pairs(cards) do if not refs.resolved then unresolved=unresolved+1 end end
    runtime.macroPlacementCount=total;runtime.unresolvedCount=unresolved
    raw(148).Text="Auto Upgrade · "..total
    autoSwitch.Text=upgradePaused and "AUTO OFF" or "AUTO ON"
    help.Visible=total==0 or unresolved>0
    help.Size=UDim2.new(1,0,0,28)
    help.Text=total==0 and "Select a macro. Default target: 0." or (unresolved>0 and
        (runtime.catalogState=="reading" and "Loading unit names and portraits…" or "Unit data unavailable. Press INFO.") or
        "− / +: target. 0: no upgrades. SAVE stores your plan.")
end
bind(previous,function() page=math.max(1,page-1);refreshPlan() end)
bind(nextPage,function() page=page+1;refreshPlan() end)
runtime.resolveCatalog=function()
    local source=core.entries
    if #source==0 or catalogWorking then return end
    if source==catalogSource and #source==catalogCount and os.clock()<(catalogRetry or 0) then return end
    catalogSource=source;catalogCount=#source;catalogRetry=os.clock()+20
    local ids,seen={},{}
    local needed=false
    for _,entry in ipairs(source) do
        if not seen[entry.id] then ids[#ids+1]=entry.id;seen[entry.id]=true end
        local meta=core.unitCatalog[entry.id]
        local hasIcon=meta and type(meta.icon)=="string" and meta.icon~=""
        if not meta or not Catalog.friendly(meta.displayName) or (not hasIcon and not meta.portrait and not runtime.portraitModels[entry.id]) then needed=true end
    end
    if not needed then runtime.catalogInfo="ready";runtime.catalogState="ready";return end
    if type(getgc)~="function" then runtime.catalogState="unavailable";runtime.catalogInfo="Game catalog reader unavailable in this executor. INFO contains this status.";return end
    catalogWorking=true;runtime.catalogState="reading";runtime.catalogInfo="reading game unit catalog"
    task.spawn(function()
        local ok,err=pcall(function()
            local all=getgc(true)
            assert(type(all)=="table","getgc returned no object list")
            local data={}
            for _,value in ipairs(all) do if type(value)=="table" then data[#data+1]=value end end
            local modelIndex
            local function findModel(key)
                if not modelIndex then
                    modelIndex={}
                    local count=0
                    for _,obj in ipairs(RS:GetDescendants()) do
                        count=count+1
                        if obj:IsA("Model") then
                            if modelIndex[obj.Name]~=nil then modelIndex[obj.Name]=false else modelIndex[obj.Name]=obj end
                        end
                        if count%400==0 then task.wait() end
                    end
                end
                return modelIndex[key] or nil
            end
            local ignore={[core.unitCatalog]=true,[core.entries]=true}
            for _,meta in pairs(core.unitCatalog) do ignore[meta]=true end
            local resolved=Catalog.resolve(ids,data,{asset=Portrait.asset,ignore=ignore,
                alive=function() return runtime.alive and core.entries==source end,
                yield=function() task.wait() end,
                isModel=function(value) return typeof(value)=="Instance" and value:IsA("Model") end,
                findModel=findModel,
            })
            if not runtime.alive or core.entries~=source then return end
            local ready,changed=0,false
            for id,value in pairs(resolved) do
                local previous=core.unitCatalog[id] or {};local meta={}
                for k,v in pairs(previous) do meta[k]=v end
                if value.displayName and (not meta.customName or not Catalog.friendly(meta.displayName)) then meta.displayName=value.displayName end
                if value.icon then meta.icon=value.icon end
                if value.modelName then meta.modelName=value.modelName end
                if value.model then
                    if not runtime.portraitModels[id] then
                        local cloned,model=pcall(Portrait.clone,value.model)
                        if cloned then runtime.portraitModels[id]=model end
                    end
                    if not meta.portrait then
                        local captured,portrait=pcall(Portrait.capture,value.model)
                        if captured and portrait then
                            local valid,clean=pcall(Portrait.validate,portrait,Recorder.validateCFrame)
                            if valid then meta.portrait=clean end
                        end
                    end
                end
                core.unitCatalog[id]=meta
                if meta.displayName~=previous.displayName or meta.icon~=previous.icon or meta.modelName~=previous.modelName or meta.portrait~=previous.portrait then changed=true end
                if meta.displayName and ((meta.icon and meta.icon~="") or meta.portrait or runtime.portraitModels[id]) then ready=ready+1 end
            end
            if changed then core.dirty=true end
            runtime.catalogState=ready==#ids and "ready" or "partial"
            runtime.catalogInfo="Catalog: "..ready.."/"..#ids.." units resolved. Unresolved cards are not replaced with placeholders."
        end)
        catalogWorking=false
        if not ok and runtime.alive then runtime.catalogState="unavailable";runtime.catalogInfo=tostring(err):sub(1,180) end
    end)
end

